from typing import List, Tuple

def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    """ Given a simple connected undirected graph with n vertices and edges (where each edge is 
    represented as (u, v, w) meaning vertices u and v are connected with weight w), and two 
    sequences a and b of the same length, find the minimum possible sum of path weights.

    For any path in the graph, its weight is defined as the maximum weight of any edge in that path.
    f(x, y) is defined as the minimum possible path weight from vertex x to vertex y.

    The task is to permute sequence b such that the sum of f(a[i], b[i]) for all i is minimized.

    Args:
        n: Number of vertices (vertices are numbered 1 to n)
        edges: List of edges, each edge is (u, v, w) where u < v
        a: First sequence of vertex numbers
        b: Second sequence of vertex numbers (to be permuted)

    Returns:
        The minimum possible sum of f(a[i], b[i]) after optimally permuting b
    """
    # Step 1: Build MST using Kruskal's algorithm
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    sorted_edges = sorted(edges, key=lambda x: x[2])
    mst_edges = []
    count = 0
    for u, v, w in sorted_edges:
        if union(u, v):
            mst_edges.append((u, v, w))
            count += 1
            if count == n - 1:
                break

    # Step 2: Build adjacency list for MST
    mst_adj = {i: [] for i in range(1, n + 1)}
    for u, v, w in mst_edges:
        mst_adj[u].append((v, w))
        mst_adj[v].append((u, w))

    # Step 3: Function to compute f(u, v) = max edge weight on path from u to v in MST
    def get_max_edge(u, v):
        if u == v:
            return 0
        parent_map = {u: (None, 0)}
        queue = [u]
        visited = {u}
        found = False
        while queue:
            curr = queue.pop(0)
            if curr == v:
                found = True
                break
            for neighbor, weight in mst_adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent_map[neighbor] = (curr, weight)
                    queue.append(neighbor)
        if not found:
            return 0
        max_w = 0
        curr = v
        while curr != u:
            p, w = parent_map[curr]
            if w > max_w:
                max_w = w
            curr = p
        return max_w

    k = len(a)
    if k == 0:
        return 0

    # Step 4: Build cost matrix
    cost_matrix = [[0] * k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            cost_matrix[i][j] = get_max_edge(a[i], b[j])

    # Step 5: Solve assignment problem using Hungarian algorithm (minimization)
    INF = 10**18
    u = [0] * (k + 1)
    v = [0] * (k + 1)
    p = [0] * (k + 1)
    way = [0] * (k + 1)

    for i in range(1, k + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (k + 1)
        used = [False] * (k + 1)

        while p[j0] != 0:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0

            for j in range(1, k + 1):
                if not used[j]:
                    cur = cost_matrix[i0-1][j-1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j

            for j in range(0, k + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta

            j0 = j1

        while j0 != 0:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1

    return -v[0]

