from typing import List, Tuple
from itertools import combinations

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX == rootY:
            return False
        if self.rank[rootX] < self.rank[rootY]:
            self.parent[rootX] = rootY
        elif self.rank[rootX] > self.rank[rootY]:
            self.parent[rootY] = rootX
        else:
            self.parent[rootY] = rootX
            self.rank[rootX] += 1
        return True

def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    if m < n - 1:
        return -1  # Not possible to form a spanning tree

    min_cost = float('inf')

    # Generate all combinations of n-1 edges
    for edge_subset in combinations(edges, n - 1):
        uf = UnionFind(n)
        total_weight = 0
        valid = True

        for u, v, w in edge_subset:
            if not uf.union(u, v):
                valid = False
                break
            total_weight += w

        if valid:
            # Check if all vertices are connected
            root = uf.find(1)
            connected = all(uf.find(i) == root for i in range(1, n + 1))
            if connected:
                cost = total_weight % k
                if cost < min_cost:
                    min_cost = cost

    return min_cost if min_cost != float('inf') else -1
